import{cityTowers as v,sections as z,outline as T,WATER_Y as S}from"./city.min.js";export const WASHERS={at:[[155,-355],[44,-339]],hours:[8,17],width:7,stand:1.4,floor:3.8,minutes:{down:46,up:7,across:7},late:[0,23],reach:110,parked:2.4};export function washerFaces(o=v()){return WASHERS.at.map(([t,r])=>{let s=o[0];for(const e of o)Math.hypot(e.x-t,e.z-r)<Math.hypot(s.x-t,s.z-r)&&(s=e);const a=z(s),n=a[a.length-1],c=T(s,n.at),u=c.map(e=>e[0]),i=c.map(e=>e[1]),m=Math.min(...u),h=Math.max(...u);return{tower:s,x:(m+h)/2,z:Math.max(...i),yaw:0,length:h-m,roof:S+s.base+n.y1,travel:Math.min(WASHERS.reach,n.y1-n.y0-6)}})}export function drops(o){return Math.max(1,Math.floor((o.length-2)/WASHERS.width))}export function dropAt(o,t){const r=drops(o);return(t+.5-r/2)*WASHERS.width}const M=o=>{const t=Math.min(1,Math.max(0,o));return t*t*(3-2*t)};function g(o,t){if(t===1)return 0;const r=(o%(2*t)+2*t)%(2*t);return r<t?r:2*t-1-r}export function washerAt(o,t,r=0,s=0){const a=drops(o),{down:n,up:c,across:u}=WASHERS.minutes,i=n+c+u,h=(t.getHours()+t.getMinutes()/60+t.getSeconds()/3600-WASHERS.hours[0])*60-WASHERS.late[r%WASHERS.late.length],e=(WASHERS.hours[1]-WASHERS.hours[0])*60,p=Math.floor((t.getTime()-t.getTimezoneOffset()*6e4)/864e5),l=Math.floor(e/i);if(h<0)return{along:dropAt(o,g(p*l,a)),down:0,working:!1};if(h>=l*i)return{along:dropAt(o,g((p+1)*l,a)),down:0,working:!1};const x=Math.floor(h/i),f=dropAt(o,g(p*l+x,a));if(s>.25)return{along:f,down:0,working:!1};const w=h-x*i;if(w<n){const d=Math.max(1,Math.floor(o.travel/WASHERS.floor)),y=w/n*d,k=Math.floor(y);return{along:f,down:(k+M((y-k-.75)/.25))/d*o.travel,working:!0}}if(w<n+c)return{along:f,down:o.travel*(1-M((w-n)/c)),working:!0};const A=dropAt(o,g(p*l+x+1,a));return{along:f+(A-f)*M((w-n-c)/u),down:0,working:!0}}
